#!/usr/bin/env python3
"""Experiment registry at a glance.  python3 tools/status.py [--write]
--write regenerates experiments/INDEX.md (generated file; never edit)."""
import sys
from datetime import date
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from _facts import ROOT, experiments, runs, frozen_facts, adrs  # noqa: E402


def rows():
    facts, _ = frozen_facts()
    frozen_runs = {(f["_experiment"], f["_run"]) for f in facts.values()}
    adr_index = {}
    for a in adrs():
        if a.get("experiment") and a["experiment"] != "none":
            adr_index.setdefault(a["experiment"], []).append(a.get("id", a["_file"]))
    out = []
    for eid, e in experiments().items():
        rs = runs(eid)
        latest = sorted(rs)[-1] if rs else "-"
        variant = rs[latest].get("variant", "-") if rs else "-"
        inflight = sum(1 for r in rs.values() if r.get("status") == "dispatched")
        out.append({
            "experiment": eid, "status": e.get("status", "?"),
            "targets": ",".join(t["claim"] for t in e.get("targets", [])),
            "runs": len(rs), "frozen": sum(1 for r in rs if (eid, r) in frozen_runs),
            "in_flight": inflight, "latest": f"{latest} ({variant})" if rs else "-",
            "adrs": ",".join(adr_index.get(eid, [])) or "-",
            "title": (e.get("title") or "")[:60],
        })
    return out


def table(rs):
    cols = ["experiment", "status", "targets", "runs", "frozen", "in_flight", "latest", "adrs", "title"]
    w = {c: max(len(c), *(len(str(r[c])) for r in rs)) if rs else len(c) for c in cols}
    line = lambda r: "| " + " | ".join(str(r[c]).ljust(w[c]) for c in cols) + " |"
    head = line({c: c for c in cols}); sep = "|" + "|".join("-" * (w[c] + 2) for c in cols) + "|"
    return "\n".join([head, sep] + [line(r) for r in rs])


def main():
    rs = rows()
    t = table(rs)
    print(t)
    if "--write" in sys.argv:
        out = ROOT / "experiments" / "INDEX.md"
        out.write_text(f"# Experiment registry\n\nGENERATED by `tools/status.py --write` on {date.today().isoformat()}; do not edit.\n\n{t}\n")
        print(f"\n[status] wrote {out.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
